class Solution {
  public boolean canDistribute(int[] nums, int[] quantity) {
    Map<Integer, Integer> freq = new HashMap<>();
    for (int x : nums) freq.merge(x, 1, Integer::sum);
    int m = quantity.length, full = (1 << m) - 1;
    int[] need = new int[1 << m]; // total demand of each set of customers
    for (int mask = 1; mask <= full; mask++) {
      int low = Integer.numberOfTrailingZeros(mask);
      need[mask] = need[mask & (mask - 1)] + quantity[low];
    }
    boolean[] served =
        new boolean[1 << m]; // customers in the mask are satisfied by the values so far
    served[0] = true;
    for (int count : freq.values()) {
      boolean[] next = served.clone();
      for (int mask = 0; mask <= full; mask++) {
        if (!served[mask]) continue;
        int rest = full ^ mask;
        for (int sub = rest; sub > 0; sub = (sub - 1) & rest) {
          if (need[sub] <= count) next[mask | sub] = true;
        }
      }
      served = next;
      if (served[full]) return true;
    }
    return served[full];
  }
}
